const renumberColumnPositions = `-- name: RenumberColumnPositions :exec
WITH ranked AS (
  SELECT id, (row_number() OVER (ORDER BY position, id))::numeric AS rn
  FROM items
  WHERE column_id = $1
)
UPDATE items i SET position = ranked.rn FROM ranked WHERE i.id = ranked.id
`

func (q *Queries) RenumberColumnPositions(ctx context.Context, dollar_1 pgtype.UUID) error {
	_, err := q.db.Exec(ctx, renumberColumnPositions, dollar_1)
	return err
}

